t.script:
if ('serviceWorker' in navigator) {
    window.addEventListener('load', function() {
        navigator.serviceWorker.register('/service-worker.js');
    });
}

// Robust Install Pattern
let deferredPrompt;
window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    const btn = document.getElementById('pwaInstallBtn');
    if(btn) btn.style.display = 'block';
});

document.addEventListener('click', (e) => {
     if (e.target.closest('#pwaInstallBtn')) {
         if (deferredPrompt) {
             deferredPrompt.prompt();
             deferredPrompt.userChoice.then((choiceResult) => {
                 if (choiceResult.outcome === 'accepted') {
                     document.getElementById('pwaInstallBtn').style.display = 'none';
                 }
                 deferredPrompt = null;
             });
         }
     }
});

// Load scanner library asynchronously AFTER page renders
window.addEventListener('DOMContentLoaded', function() {
    var script = document.createElement('script');
    script.src = 'https://unpkg.com/html5-qrcode@2.3.8/esm/html5-qrcode.min.js';
    script.async = true;
    script.onerror = function() {
        console.warn('html5-qrcode CDN failed. Scanner will show error on first use.');
    };
    document.body.appendChild(script);
});

function handleQuickPhoto(input) {
    if (input.files && input.files[0]) {
        var btn = document.getElementById('quickPhotoBtn');
        var originalHtml = btn.innerHTML;
        btn.innerHTML = ' Processing...';

        window.compressImage(input.files[0], function(base64) {
            document.getElementById('quickPhoto64').value = base64;
            // Remove name from file input to prevent uploading big file
            input.removeAttribute('name');
            document.getElementById('quickPhotoForm').submit();
        });
    }
}

function updateDeliveryState(pickingId, stateId) {
    fetch('/my/delivery/update_state', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                picking_id: pickingId,
                state_id: stateId
            }
        })
    }).then(res => res.json()).then(data => {
        if(data.result && data.result.success) {
            location.reload();
        } else {
            alert('Error updating state');
        }
    });
}

// Vanilla JS Signature Pad
var canvas = document.getElementById('signatureCanvas');
var ctx = canvas.getContext('2d');
var drawing = false;
var hasSigned = false;

// Set default stroke styles
ctx.lineWidth = 2;
ctx.lineCap = 'round';
ctx.lineJoin = 'round';
ctx.strokeStyle = '#333';

// Mouse events
canvas.addEventListener('mousedown', function(e) { drawing = true; ctx.beginPath(); ctx.moveTo(e.offsetX, e.offsetY); });
canvas.addEventListener('mousemove', function(e) { if(drawing) { ctx.lineTo(e.offsetX, e.offsetY); ctx.stroke(); hasSigned = true; } });
canvas.addEventListener('mouseup', function() { drawing = false; });

// Touch events (Mobile)
canvas.addEventListener('touchstart', function(e) { 
    e.preventDefault(); 
    var touch = e.touches[0];
    var rect = canvas.getBoundingClientRect();
    drawing = true; 
    ctx.beginPath(); 
    ctx.moveTo(touch.clientX - rect.left, touch.clientY - rect.top); 
});
canvas.addEventListener('touchmove', function(e) { 
    e.preventDefault(); 
    if(drawing) { 
        var touch = e.touches[0];
        var rect = canvas.getBoundingClientRect();
        ctx.lineTo(touch.clientX - rect.left, touch.clientY - rect.top); 
        ctx.stroke(); 
        hasSigned = true;
    } 
});
canvas.addEventListener('touchend', function(e) { e.preventDefault(); drawing = false; });

function resizeCanvas() {
    var container = canvas.parentElement;
    var rect = container.getBoundingClientRect();
    // Maintain aspect ratio (5:3), max 600px wide
    var newWidth = Math.min(rect.width - 24, 600); // 24px for padding
    var newHeight = (newWidth * 3) / 5;

    // Update canvas resolution
    canvas.width = newWidth;
    canvas.height = newHeight;

    // Reset line styling
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#333';
}

// Call on page load and orientation change
window.addEventListener('load', resizeCanvas);
window.addEventListener('orientationchange', resizeCanvas);
window.addEventListener('resize', debounce(resizeCanvas, 250));

// Debounce helper
function debounce(func, wait) {
    let timeout;
    return function() {
        clearTimeout(timeout);
        timeout = setTimeout(func, wait);
    };
}

function clearSignature() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    hasSigned = false;
    document.getElementById('signatureInput').value = '';
    document.getElementById('signaturePlaceholder').style.display = 'block';
}

function updatePhotoLabel(input) {
    var label = document.getElementById('photoLabel');
    if(input.files && input.files[0]) {
        label.textContent = "Processing...";
        label.style.display = 'block';

        // Compress immediately using global function
        window.compressImage(input.files[0], function(base64) {
            document.getElementById('photo64').value = base64;
            label.textContent = input.files[0].name + " (Optimized)";
            label.className = "text-center small text-success pb-2";
        });
    } else {
        label.style.display = 'none';
        document.getElementById('photo64').value = '';
    }
}

function updateRequirements(radio) {
    var section = document.getElementById('requirementsSection');
    section.style.display = 'block';

    var reqSig = radio.getAttribute('data-require-signature') === 'True';
    var reqPhoto = radio.getAttribute('data-require-photo') === 'True';
    var reqName = radio.getAttribute('data-require-receiver-name') === 'True';

    document.getElementById('signatureBlock').style.display = reqSig ? 'block' : 'none';
    if (reqSig) {
        // Resize canvas when it becomes visible
        setTimeout(() => resizeCanvas(), 50);
    }

    document.getElementById('photoBlock').style.display = reqPhoto ? 'block' : 'none';
    document.getElementById('receiverNameBlock').style.display = reqName ? 'block' : 'none';

    // Update Help/Legal Text
    var stateId = radio.value;
    var helpText = document.getElementById('help_text_' + stateId).textContent.trim();
    var legalText = document.getElementById('legal_text_' + stateId).textContent.trim();

    var infoSection = document.getElementById('stateInfoSection');
    var helpAlert = document.getElementById('helpAlert');
    var legalAlert = document.getElementById('legalAlert');

    if (helpText || legalText) {
        infoSection.style.display = 'block';

        if (helpText) {
            document.getElementById('helpAlertText').textContent = helpText;
            helpAlert.style.setProperty('display', 'flex', 'important');
        } else {
            helpAlert.style.setProperty('display', 'none', 'important');
        }

        if (legalText) {
             document.getElementById('legalAlertText').textContent = legalText;
             legalAlert.style.setProperty('display', 'block', 'important');
        } else {
             legalAlert.style.setProperty('display', 'none', 'important');
        }
    } else {
        infoSection.style.display = 'none';
    }

    resizeCanvas(); // Ensure canvas is sized correctly if revealed
}

function showToast(msg, bgClass='bg-warning') {
     var toast = document.getElementById('offlineToast');
     var toastBody = toast.querySelector('.toast');
     document.getElementById('offlineToastMsg').textContent = msg;
     toastBody.className = 'toast show align-items-center text-white border-0 ' + bgClass;
     toast.style.display = 'block';
     setTimeout(() => { toast.style.display = 'none'; }, 4000);
}

// OFFLINE SYNC LOGIC
// Use a dynamic key unique per delivery
const PENDING_KEY = 'pending_delivery_' + '';

function saveOfflineData(formData) {
    try {
        const data = {};
        formData.forEach((value, key) => data[key] = value);
        data.timestamp = new Date().toISOString();
        localStorage.setItem(PENDING_KEY, JSON.stringify(data));
        showToast('Connection lost. Saved to device (Draft).', 'bg-warning');
    } catch(e) {
        console.error('Storage failed', e);
        alert('Storage full. Cannot save offline.');
    }
}

function checkAndSync() {
     const pendingData = localStorage.getItem(PENDING_KEY);
     if (pendingData && navigator.onLine) {
         showToast('Connection restored. Syncing...', 'bg-info');
         const data = JSON.parse(pendingData);

         // Reconstruct FormData
         const formData = new FormData();
         for (const key in data) {
             formData.append(key, data[key]);
         }

         // Submit via fetch
         fetch(document.getElementById('finalizeForm').action, {
             method: 'POST',
             body: formData
         }).then(response => {
             if (response.ok || response.redirected) {
                 localStorage.removeItem(PENDING_KEY);
                 showToast('Sync Complete! Redirecting...', 'bg-success');
                 if (response.redirected) {
                     window.location.href = response.url;
                 } else {
                     window.location.href = '/my/delivery';
                 }
             } else {
                 console.error("Sync server error");
             }
         }).catch(err => {
             console.log("Sync failed again, keeping data.");
         });
     }
}

// Check on load and online event
window.addEventListener('load', () => {
     if(localStorage.getItem(PENDING_KEY)) {
         showToast('You have unsynced data. Waiting for connection...', 'bg-warning');
         checkAndSync();
     }
});
window.addEventListener('online', checkAndSync);

function resizeCanvas() {
    var ratio = Math.max(window.devicePixelRatio || 1, 1);
    // This part can clear the canvas, so only do it if necessary or handle state
    // Simple approach: rely on CSS 100% width
}

function prepareSubmit(e) {
    e.preventDefault(); // Control submission manually

    var selectedState = document.querySelector('input[name="delivery_state_id"]:checked');
    if (!selectedState) {
        alert("Please select a result state.");
        return; 
    }

    var isSigMandatory = selectedState.getAttribute('data-mandatory-signature') === 'True';
    var isPhotoMandatory = selectedState.getAttribute('data-mandatory-photo') === 'True';
    var isNameMandatory = selectedState.getAttribute('data-mandatory-receiver-name') === 'True';

    // 1. Signature
    var dataUrl = canvas.toDataURL();
    // We trust 'hasSigned' if canvas is visible, unless user cleared it.
    if (document.getElementById('signatureBlock').style.display !== 'none' && isSigMandatory && !hasSigned) {
        alert('Signature is required for this state.');
        return false;
    }
    document.getElementById('signatureInput').value = dataUrl;

    // 2. Photo
    if (document.getElementById('photoBlock').style.display !== 'none' && isPhotoMandatory) {
        var photoInput = document.getElementById('photoInput');
        var photo64 = document.getElementById('photo64').value;

        if ((!photoInput.files || photoInput.files.length === 0) && !photo64) {
             alert('Photo evidence is required for this state.');
             return false;
        }
    }

    if (document.getElementById('photo64').value) {
         document.getElementById('photoInput').removeAttribute('name');
    }

    // 3. Receiver Name
    if (document.getElementById('receiverNameBlock').style.display !== 'none' && isNameMandatory) {
         var nameInput = document.getElementById('receiverNameInput');
         if (!nameInput.value.trim()) {
             alert('Receiver Name is required.');
             return false;
         }
    }

    // SUBMISSION LOGIC
    var form = document.getElementById('finalizeForm');
    var formData = new FormData(form);
    var btn = e.target;
    // Fix: Ensure we are targeting button if click was on icon
    if (btn.tagName === 'I') btn = btn.closest('button');

    var originalText = btn.innerHTML;

    if (navigator.onLine) {
         btn.innerHTML = ' Sending...';
         btn.disabled = true;

         fetch(form.action, {
             method: 'POST',
             body: formData
         }).then(response => {
             if (response.ok || response.redirected) {
                 window.location.href = response.url || '/my/delivery';
             } else {
                 // Server Error - alert keeping offline? No, server error means connected but failed logic.
                 alert('Server Error. Please try again.');
                 btn.innerHTML = originalText;
                 btn.disabled = false;
             }
         }).catch(error => {
             // Network Error -> Offline Fallback
             saveOfflineData(formData);
             btn.innerHTML = originalText;
             btn.disabled = false;
         });
    } else {
         // Offline immediately
         saveOfflineData(formData);
    }
}
